-        const jid =
-          this.name +
-          "@odnoklassniki.ru/" +
-          Services.strings
-            .createBundle("chrome://branding/locale/brand.properties")
-            .GetStringFromName("brandShortName");
-        this._jid = this._parseJID(jid);
-      } else {
-        this._jid = this._parseJID(this.name);
