-    },
-  };
-  return OdnoklassnikiAccount;
-});
+  // Nothing to do.
+  unInit() {},
+  remove() {},
+};

 export function OdnoklassnikiProtocol() {}
 OdnoklassnikiProtocol.prototype = {
@@ -74,10 +45,7 @@ OdnoklassnikiProtocol.prototype = {
   get iconBaseURI() {
     return "chrome://prpl-odnoklassniki/skin/";
